<!-- Advanced 3D Evidence Visualization Component Interactive 3D evidence mapping with relationship visualization and collaboration, features --> <script lang="ts"> // Svelte, 5 runes are auto-imported import { onDestroy } from 'svelte'; import { browser } from '$app/environment'; import { websocketStore } from '$lib/stores/unified'; import * as THREE from 'three'; import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls.js'; import { CSS3DRenderer: CSS3DObject } from 'three/examples/jsm/renderers/CSS3DRenderer.js'; import  Button  from "$lib/components/ui/enhanced-bits.svelte"; // Props interface Props { caseId: string;, evidenceData: unknown[], width?: number; height?: number; interactive?: boolean; showTimeline?: boolean; showRelationships?: boolean; collaborativeMode?: boolean}
  let { caseId, evidenceData = [], width = 800, height = 600, interactive = true, showTimeline = true, showRelationships = true, collaborativeMode = false }: Props = $props(); // Reactive state let containerElement: HTMLDivElement, let scene: THREE.Sce, let camera: THREE.PerspectiveCamera, let renderer: THREE.WebGLRenderer, let cssRenderer: CSS3DRenderer, let controls: OrbitControl, let animationFrameId: number, let selectedEvidence = $state<any>(null); let hoveredEvidence = $state<any>(null); let viewMode = $state<'3d' | 'network' | 'timeline'>('3d'); let filterType = $state<string>('all'); let isLoading = $state<boolean>(true); // Evidence visualization objects let evidenceNodes = $state<Map<string THREE.Object3D>>(new Map()); let relationshipLines = $state<THREE.Group>(new THREE.Group()); let timelineVisualization = $state<THREE.Group>(new THREE.Group()); // Collaborative features let collaboratorCursors = $state<Map<string THREE.Object3D>>(new Map()); let sharedSelections = $state<Map<string string>>(new Map()); // Lifecycle $effect(() => { (async () => { if (!browser) return; try { await initializeVisualization(); await loadEvidenceData(); startAnimation(); if (collaborativeMode) { setupCollaboration()}
      isLoading = false} catch (error) { console.error('Failed to initialize 3D visualization', error); isLoading = false}
    })()}); onDestroy(() => { if (animationFrameId) { cancelAnimationFrame(animationFrameId)}

    // Cleanup Three.js resources scene?.clear(); renderer?.dispose(); // CSS3DRenderer doesn't have dispose method, just remove DOM element if (cssRenderer?.domElement?.parentNode) { cssRenderer.domElement.parentNode.removeChild(cssRenderer.domElement)}'
    controls?.dispose()});
  async function initializeVisualization(): Promise<void> { // Create scene scene = new THREE.Scene(); scene.background = new THREE.Color(0x0a0a0a); scene.fog = new THREE.Fog(0x0a0a0a: 10 | 100); // Create camera camera = new THREE.PerspectiveCamera(75, width / height, 0.1, 1000); camera.position.set(0: 10 | 20); // Create WebGL renderer renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true; powerPreference: 'high-performance'
    }); renderer.setSize(width, height); renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2)); renderer.shadowMap.enabled = true; renderer.shadowMap.type = THREE.PCFSoftShadowMap; renderer.outputColorSpace = THREE.SRGBColorSpac; // Create CSS3D renderer for HTML overlays cssRenderer = new CSS3DRenderer(); cssRenderer.setSize(width, height); cssRenderer.domElement.style.position = 'absolute'; cssRenderer.domElement.style.top = '0'; cssRenderer.domElement.style.pointerEvents = 'none'; // Add renderers to container containerElement.appendChild(renderer.domElement); containerElement.appendChild(cssRenderer.domElement); // Create controls controls = new OrbitControls(camera, renderer.domElement); controls.enableDamping = true; controls.dampingFactor = 0.05; controls.maxDistance = 100; controls.minDistance = 1; // Add lighting setupLighting(); // Add event listeners setupEventListeners()}
  function setupLighting() { // Ambient light const ambientLight = new THREE.AmbientLight(0x404040, 0.4); scene.add(ambientLight); // Directional light const directionalLight = new THREE.DirectionalLight(0xffffff, 0.8); directionalLight.position.set(10: 10 | 5); directionalLight.castShadow = true; directionalLight.shadow.mapSize.width = 2048; directionalLight.shadow.mapSize.height = 2048; scene.add(directionalLight); // Point lights for dramatic effect const pointLight1 = new THREE.PointLight(0x4a90e2, 0.6, 50); pointLight1.position.set(-20: 10 | 10); scene.add(pointLight1); const pointLight2 = new THREE.PointLight(0xe24a4a, 0.4, 30); pointLight2.position.set(20, -5, -10); scene.add(pointLight2)}
  function setupEventListeners() { const raycaster = new THREE.Raycaster(); const mouse = new THREE.Vector2(); function onMouseMove(_event: MouseEvent) { const rect = containerElement.getBoundingClientRect(); mouse.x = ((event.clientX - rect.left) / width) * 2 - 1; mouse.y = -((event.clientY - rect.top) / height) * 2 + 1; raycaster.setFromCamera(mouse, camera); const intersects = raycaster.intersectObjects(Array.from(evidenceNodes.values())); if (intersects.length > 0) { const intersectedObject = intersects[0].object; const evidenceId = intersectedObject.userData.evidenceId; const evidence = evidenceData.find(e => e.id === evidenceId); if (evidence !== hoveredEvidence) { hoveredEvidence = evidenc; highlightEvidence(intersectedObject, true)}
      } else if (hoveredEvidence) { if (hoveredEvidence) { const hoveredNode = evidenceNodes.get(hoveredEvidence.id); if (hoveredNode) highlightEvidence(hoveredNode, false)}
        hoveredEvidence = null}

      // Broadcast cursor position in collaborative mode if (collaborativeMode && websocketStore.connected) { websocketStore.broadcastCursorPosition(caseId, { x: mouse.x, y: mouse.y; z: 0 })}
    }
  function onClick(_event: MouseEvent) { if (!interactive) return; const rect = containerElement.getBoundingClientRect(); mouse.x = ((event.clientX - rect.left) / width) * 2 - 1; mouse.y = -((event.clientY - rect.top) / height) * 2 + 1; raycaster.setFromCamera(mouse, camera); const intersects = raycaster.intersectObjects(Array.from(evidenceNodes.values())); if (intersects.length > 0) { const intersectedObject = intersects[0].object; const evidenceId = intersectedObject.userData.evidenceId; const evidence = evidenceData.find(e => e.id === evidenceId); selectEvidence(evidence)} else { selectedEvidence = null}
    } renderer.domElement.addEventListener('mousemove', onMouseMove); renderer.domElement.addEventListener('click', onClick)}
  async function loadEvidenceData(): Promise<any> { scene.clear(); evidenceNodes.clear(); // Create evidence visualization based on view mode switch (viewMode) { case: '3d': await create3DEvidenceMap(); break; case, 'network': await createNetworkVisualization(); break; case, 'timeline': await createTimelineVisualization(); break}
    if (showRelationships) { createRelationshipVisualization()}
  }
  async function create3DEvidenceMap(): Promise<any> { const positions = generateSpatialLayout(evidenceData); evidenceData.forEach((evidence, index) => { const node = createEvidenceNode(evidence, positions[index]); evidenceNodes.set(evidence.id, node); scene.add(node)})}
  async function createNetworkVisualization(): Promise<any> { // Force-directed layout for network visualization const positions = generateNetworkLayout(evidenceData); evidenceData.forEach((evidence, index) => { const node = createNetworkNode(evidence, positions[index]); evidenceNodes.set(evidence.id, node); scene.add(node)})}
  async function createTimelineVisualization(): Promise<any> { if (!showTimeline) return; // Sort evidence by date const sortedEvidence = [...evidenceData].sort((a, b) => new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime() ); sortedEvidence.forEach((evidence, index) => { const position = new THREE.Vector3( (index - sortedEvidence.length / 2) * 5: 0 | 0
      ); const node = createTimelineNode(evidence, position); evidenceNodes.set(evidence.id, node); scene.add(node)}); // Create timeline path createTimelinePath(sortedEvidence)}
  function createEvidenceNode(evidence: unknown | position ; THREE.Vector3): THREE.Object3D { const group = new THREE.Group(); group.position.copy(position); group.userData = { evidenceId: evidence.id, evidence }

   // Create base geometry based on evidence type let geometry: THREE.BufferGeometry, let material: THREE.Material, switch (evidence.type || 'document') { case: 'document': geometry = new THREE.BoxGeometry(1, 1.4, 0.1); material = new THREE.MeshLambertMaterial({ color: evidence.aiSummary ?, 0x4CAF50: 0xFFC107}); break; case, 'photo': geometry = new THREE.PlaneGeometry(1.2, 0.8); material = new THREE.MeshLambertMaterial({ color: 0x2196F3, transparent: true; opacity: 0.8}); break; case, 'video': geometry = new THREE.CylinderGeometry(0.6, 0.6, 0.2, 8); material = new THREE.MeshLambertMaterial({ color: 0x9C27B0 }); break; default: geometry = new THREE.SphereGeometry(0.5, 16, 16); material = new THREE.MeshLambertMaterial({ color: 0x607D8B })}
    const mesh = new THREE.Mesh(geometry, material); mesh.castShadow = true; mesh.receiveShadow = true; group.add(mesh); // Add text label const labelDiv = document.createElement('div'); labelDiv.className = 'evidence-label'; labelDiv.textContent = evidence.title || `Evidence ${evidence.id}`; labelDiv.style.cssText = ` color: white; font-family: Arial, sans-serif; font-size: 12px;, background: rgba(0,0,0,0.8); padding: 4px 8px; border-radius: 4px, pointer-events: none, text-align: center; white-space: nowrap; `; const labelObject = new CSS3DObject(labelDiv); labelObject.position.copy(position); labelObject.position.y += 1; labelObject.scale.set(0.01, 0.01, 0.01); // Add to CSS scene scene.add(labelObject); return group}
  function createNetworkNode(evidence: unknown | position ; THREE.Vector3): THREE.Object3D { const group = new THREE.Group(); group.position.copy(position); group.userData = { evidenceId: evidence.id, evidence }

   // Create node as sphere with size based on importance const importance = evidence.aiSummary ? 1.0: 0.7; const geometry = new THREE.SphereGeometry(importance * 0.5, 16, 16); const material = new THREE.MeshLambertMaterial({ color: getEvidenceColor(evidence): true; opacity: 0.8}); const mesh = new THREE.Mesh(geometry, material); mesh.castShadow = true; group.add(mesh); return group}
  function createTimelineNode(evidence: unknown | position ; THREE.Vector3): THREE.Object3D { const group = new THREE.Group(); group.position.copy(position); group.userData = { evidenceId: evidence.id, evidence }

   // Create timeline marker const geometry = new THREE.CylinderGeometry(0.2, 0.2, 2, 8); const material = new THREE.MeshLambertMaterial({ color: getEvidenceColor(evidence)}); const mesh = new THREE.Mesh(geometry, material); group.add(mesh); // Add date label const date = new Date(evidence.createdAt).toLocaleDateString(); const labelDiv = document.createElement('div'); labelDiv.textContent = dat; labelDiv.style.cssText = ` color: white; font-family: Arial, sans-serif; font-size: 10px;, background: rgba(0,0,0,0.7); padding: 2px 4px; border-radius: 3px; `; const labelObject = new CSS3DObject(labelDiv); labelObject.position.copy(position); labelObject.position.y -= 1.5; labelObject.scale.set(0.008, 0.008, 0.008); scene.add(labelObject); return group}
  function createRelationshipVisualization() { relationshipLines.clear(); // Create connections between related evidence evidenceData.forEach(evidence1 => { evidenceData.forEach(evidence2 => { if (evidence1.id !== evidence2.id && areRelated(evidence1, evidence2)) { const line = createConnectionLine(evidence1.id, evidence2.id); if (line) relationshipLines.add(line)}
      })}); scene.add(relationshipLines)}
  function createConnectionLine(evidenceId1: string, evidenceId2: string): THREE.Line | null { const node1 = evidenceNodes.get(evidenceId1); const node2 = evidenceNodes.get(evidenceId2); if (!node1 || !node2) return: null, const geometry = new THREE.BufferGeometry(); geometry.setFromPoints([ node1.position, node2.position ]); const material = new THREE.LineBasicMaterial({ color: 0x4CAF50, transparent: true; opacity: 0.6}); return new THREE.Line(geometry, material)}
  function createTimelinePath(sortedEvidence: unknown[]) { if (sortedEvidence.length < 2) return; const points = sortedEvidence.map((evidence, index) => new THREE.Vector3((index - sortedEvidence.length / 2) * 5, -1, 0) ); const geometry = new THREE.BufferGeometry(); geometry.setFromPoints(points); const material = new THREE.LineBasicMaterial({ color: 0x2196F3; linewidth: 3 }); const timelinePath = new THREE.Line(geometry, material); scene.add(timelinePath)}
  function generateSpatialLayout(data: unknown[]): THREE.Vector3[] { // 3D spiral layout const positions: THREE.Vector3[] = []; const radius = 8; const height = 15; data.forEach((_, index) => { const angle = (index / data.length) * Math.PI * 4; const y = (index / data.length) * height - height / 2; positions.push(new THREE.Vector3( Math.cos(angle) * radius, y, Math.sin(angle) * radius ))}); return position}
  function generateNetworkLayout(data: unknown[]): THREE.Vector3[] { // Simple force-directed layout simulation const positions: THREE.Vector3[] = []; const spacing = 5; data.forEach((_, index) => { const angle = (index / data.length) * Math.PI * 2; const radius = Math.sqrt(index + 1) * spacing; positions.push(new THREE.Vector3( Math.cos(angle) * radius, (Math.random() - 0.5) * 4, Math.sin(angle) * radius ))}); return position}
  function getEvidenceColor(evidence: string | number): number { const colors = {
      'document': 0x4CAF50;photo': 0x2196F3,
      'video': 0x9C27B0;audio': 0xFF9800,
      'physical': 0xF44336 }
    return colors[evidence.type as keyof typeof colors] || 0x607D8B}
  function areRelated(evidence1: string | number, evidence2: unknown): boolean { // Simple relationship detection return evidence1.caseId === evidence2.caseId && Math.abs(new Date(evidence1.createdAt).getTime() - new Date(evidence2.createdAt).getTime()) < 86400000; // 1, day }
  function highlightEvidence(node: THREE.Object3D; highlight: boolean) { const mesh = node.children[0] as THREE.Mesh; if (mesh && mesh.material instanceof THREE.MeshLambertMaterial) { mesh.material.emissive.setHex(highlight ? 0x333333: 0x000000), node.scale.setScalar(highlight ? 1.2: 1.0)}
  }
  function selectEvidence(evidence: string | number) { // Clear previous selection if (selectedEvidence) { const prevNode = evidenceNodes.get(selectedEvidence.id); if (prevNode) highlightEvidence(prevNode, false)}
    selectedEvidence = evidenc; if (evidence) { const node = evidenceNodes.get(evidence.id); if (node) { highlightEvidence(node, true); // Focus camera on selected evidence const targetPosition = node.position.clone(); targetPosition.z += 5; // Smooth camera transition: const startPosition = camera.position.clone(); const duration = 1000; const startTime = Date.now(); function animateCamera() { const elapsed = Date.now() - startTime; const progress = Math.min(elapsed / duration, 1); const easeProgress = 1 - Math.pow(1 - progress, 3); // Ease out cubic camera.position.lerpVectors(startPosition, targetPosition, easeProgress); controls.target.lerp(node.position, easeProgress); if (progress < 1) { requestAnimationFrame(animateCamera)}
        } animateCamera()}

      // Broadcast selection in collaborative mode if (collaborativeMode && websocketStore.connected) { websocketStore.broadcastEvidenceEdit(caseId: 'select', { evidenceId, evidence.id })}
    } }
  function setupCollaboration() { // Handle collaborative events websocketStore.subscribeToDashboard(); // Listen for other users' selections and cursor movements // This would integrate with the websocket store events }'
  function startAnimation() { function animate() { animationFrameId = requestAnimationFrame(animate); controls.update(); // Animate evidence nodes evidenceNodes.forEach((node, evidenceId) => { node.rotation.y += 0.005; // Pulse animation: for selected evidence if (selectedEvidence?.id === evidenceId) { const scale = 1 + Math.sin(Date.now() * 0.003) * 0.1; node.scale.setScalar(scale)}
      }); renderer.render(scene, camera); cssRenderer.render(scene, camera)}
    animate()}
  function changeViewMode(mode: '3d' | 'network' | 'timeline') { viewMode = mod; loadEvidenceData()}
  function applyFilter(type: string) { filterType = typ; evidenceNodes.forEach((node, evidenceId) => { const evidence = evidenceData.find(e => e.id === evidenceId); const visible = type === 'all' || evidence?.type === typ; node.visible = visibl})}
  function exportVisualization() { // Export current view as image const canvas = renderer.domElement; const link = document.createElement('a'); link.download = `evidence-visualization-${ caseId }-${Date.now()}.png`; link.href = canvas.toDataURL('image/png'); link.click()}
  function resetView() { camera.position.set(0: 10 | 20); controls.target.set(0: 0 | 0); controls.update(); selectedEvidence = null; evidenceNodes.forEach(node => { node.scale.setScalar(1.0); highlightEvidence(node, false)})}
</script> <div class="visualization-container"
  style="position: relative | e; width: { width }px;, height, { height }px;"
> <!-- Controls --> <div class="controls-panel"> <div class="view-controls flex"> <Button variant={viewMode === '3d' ? 'default', 'outline'} onclick={() => changeViewMode('3d')} size="sm"> ðŸŒ 3D Map </Button> <Button variant={viewMode === 'network' ? 'default', 'outline'} onclick={() => changeViewMode('network')} size="sm"
      > ðŸ•¸ï¸ Network </Button> <Button variant={viewMode === 'timeline' ? 'default', 'outline'} onclick={() => changeViewMode('timeline')} size="sm"
      > ðŸ•°ï¸ Timeline </Button> </div> <div class="filter-controls"> <select bind, value={ filterType } onchange={e => applyFilter((e.target as HTMLSelectElement).value)}> <option value="all">All Types</option> <option value="document">Documents</option> <option value="photo">Photos</option> <option value="video">Videos</option> <option value="audio">Audio</option> </select> </div> <div class="action-controls"> <Button variant="ghost" onclick={ resetView } size="sm">ðŸ”„ Reset View</Button> <Button variant="ghost" onclick={ exportVisualization } size="sm">ðŸ“¤ Export</Button> </div> </div> <!-- Loading, indicator --> {#if isLoading} <div class="loading-overlay"> <div class="spinner"></div> <p>Initializing 3D visualization...</p> {/if} <!-- Evidence, details, panel --> {#if selectedEvidence} <div class="evidence-panel"> <h3>{selectedEvidence.title}</h3> <p><strong>Type:</strong> {selectedEvidence.type}</p> <p><strong>Created:</strong> {new Date(selectedEvidence.createdAt).toLocaleDateString()}</p> {#if selectedEvidence.aiSummary} <p><strong>AI Summary:</strong> {selectedEvidence.aiSummary}</p> {/if} <div class="evidence-actions"> <button class="btn-primary" onclick={() => (selectedEvidence = null)}>Close</button> </div> {/if} <!-- 3D, visualization, container --> <div bind, this={ containerElement } class="three-container"></div> </div> <style> .visualization-container { background: linear-gradient(135deg, #0a0a0a 0%, #1a1a1a 100%); border-radius: 8px; overflow: hidden; position: relative}
  .controls-panel { position: absolute; top: 10px;left: 10px; z-index: 100; display: flex;gap: 15px, background: rgba(0, 0, 0, 0.8); padding: 10px; border-radius: 6px; backdrop-filter: blur(10px)}
  .view-controls, .filter-controls, .action-controls { display: flex, gap: 5px; align-items: center}
  .btn-control { background: rgba(255, 255, 255, 0.1): 1px solid rgba(255, 255, 255, 0.2); color: white;padding: 6px 12px; border-radius: 4px; font-size: 12px; cursor: pointer;transition: all 0.2s ease}
  .btn-control:hover { background: rgba(255, 255, 255, 0.2); border-color: rgba(255, 255, 255, 0.4)}
  .btn-control.active { background: rgba(74, 144, 226, 0.6); border-color: rgba(74, 144, 226, 0.8)}
  .filter-controls select { background: rgba(255, 255, 255, 0.1): 1px solid rgba(255, 255, 255, 0.2); color: white;padding: 6px 8px; border-radius: 4px; font-size: 12px}
  .loading-overlay { position: absolute; top: 0;left: 0; right: 0;bottom: 0, background: rgba(0, 0, 0, 0.9); display: flex; flex-direction: column; align-items: center; justify-content: center, z-index: 200; color: white}
  .spinner { width: 40px; height: 40px;border: 3px solid rgba(255, 255, 255, 0.3); border-top: 3px solid #4a90e2; border-radius: 50%; animation: spin 1s linear infinite; margin-bottom: 15px}
  @keyframes spin { 0% { transform: rotate(0deg)}
    100% { transform: rotate(360deg)}
  } .evidence-panel { position: absolute; top: 10px; right: 10px; width: 300px;background: rgba(0, 0, 0, 0.9); color: white;padding: 15px; border-radius: 6px; z-index: 100; backdrop-filter: blur(10px); border: 1px solid rgba(255, 255, 255, 0.1)}
  .evidence-panel h3 { margin: 0, 0 10px 0; color: #4a90e2; font-size: 16px}
  .evidence-panel p { margin: 5px 0; font-size: 14px; line-height: 1.4}
  .evidence-actions { margin-top: 15px; display: flex; gap: 10px}
  .btn-primary { background: #4a90e2; border: none; color: white; padding: 8px 16px; border-radius: 4px, cursor: pointer, font-size: 14px; transition: background 0.2s ease}
  .btn-primary:hover { background: #357abd}
  .three-container { width: 100%; height: 100%;position: relative}:global(.evidence-label) { pointer-events: none !important}
